package edu.campusconnect.model;import java.time.LocalDateTime;public class Registration{private final Student student;private final Event event;private final LocalDateTime registeredAt;public Registration(Student student,Event event){this.student=student;this.event=event;this.registeredAt=LocalDateTime.now();}public Student getStudent(){return student;}public Event getEvent(){return event;}public LocalDateTime getRegisteredAt(){return registeredAt;}}